import{_ as l,c as i,o as e,ag as r}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"서울문화재단 규정관리규정(개정안 초안)","description":"","frontmatter":{},"headers":[],"relativePath":"regulation/규정관리규정 초안v9.md","filePath":"regulation/규정관리규정 초안v9.md"}'),o={name:"regulation/규정관리규정 초안v9.md"};function h(t,a,n,d,s,c){return e(),i("div",null,a[0]||(a[0]=[r('<h1 id="서울문화재단-규정관리규정-개정안-초안" tabindex="-1">서울문화재단 규정관리규정(개정안 초안) <a class="header-anchor" href="#서울문화재단-규정관리규정-개정안-초안" aria-label="Permalink to &quot;서울문화재단 규정관리규정(개정안 초안)&quot;">​</a></h1><h2 id="제1장-총칙" tabindex="-1">제1장 총칙 <a class="header-anchor" href="#제1장-총칙" aria-label="Permalink to &quot;제1장 총칙&quot;">​</a></h2><h3 id="제1조-목적-이-규정은-서울문화재단-이하-재단-이라-한다-의-정관-41조의-위임한-바에-따라-재단이-운용하는-모든-규정-등-규정-및-내규-의-제정·개정-및-폐지-절차와-기준을-정함으로써-상위-법령과의-정합성-규정-간-체계성-행정절차의-명확성-및-효율적-규정-운영을-확보함을-목적으로-한다" tabindex="-1">제1조(목적) 이 규정은 서울문화재단(이하 “재단”이라 한다)의 정관 41조의 위임한 바에 따라 재단이 운용하는 모든 규정 등 (규정 및 내규)의 제정·개정 및 폐지 절차와 기준을 정함으로써 상위 법령과의 정합성, 규정 간 체계성, 행정절차의 명확성 및 효율적 규정 운영을 확보함을 목적으로 한다. <a class="header-anchor" href="#제1조-목적-이-규정은-서울문화재단-이하-재단-이라-한다-의-정관-41조의-위임한-바에-따라-재단이-운용하는-모든-규정-등-규정-및-내규-의-제정·개정-및-폐지-절차와-기준을-정함으로써-상위-법령과의-정합성-규정-간-체계성-행정절차의-명확성-및-효율적-규정-운영을-확보함을-목적으로-한다" aria-label="Permalink to &quot;제1조(목적) 이 규정은 서울문화재단(이하 “재단”이라 한다)의 정관 41조의 위임한 바에 따라 재단이 운용하는 모든 규정 등 (규정 및 내규)의 제정·개정 및 폐지 절차와 기준을 정함으로써 상위 법령과의 정합성, 규정 간 체계성, 행정절차의 명확성 및 효율적 규정 운영을 확보함을 목적으로 한다.&quot;">​</a></h3><h3 id="제2조-정의-1-이-규정에서-사용하는-용어의-뜻은-다음과-같다" tabindex="-1">제2조(정의) ① 이 규정에서 사용하는 용어의 뜻은 다음과 같다. <a class="header-anchor" href="#제2조-정의-1-이-규정에서-사용하는-용어의-뜻은-다음과-같다" aria-label="Permalink to &quot;제2조(정의) ① 이 규정에서 사용하는 용어의 뜻은 다음과 같다.&quot;">​</a></h3><ol><li><strong>“규정”</strong>: 재단 운영에 관한 기본 사항으로서 <strong>이사회가 의결</strong>하여 제정·개정·폐지하는 내부 규정을 말한다.</li><li><strong>“내규”</strong>: ‘규정’의 세부 집행 절차·서식을 정하거나 특정 부서 업무를 규율하기 위하여 <strong>대표이사가 승인</strong>하여 제정·개정·폐지하는 문서를 말한다.</li><li><strong>“규정 등”</strong>: 재단이 운영하는 규정과 내규를 통칭한다.</li><li>**“제정”**이란 새로운 규정 등을 만들어 처음 시행하는 것을 말한다.</li><li>**“개정”**이란 기존 규정 등의 전부 또는 일부를 변경·보완·삭제·추가하는 것을 말한다.</li><li>**“폐지”**란 필요성이 소멸된 규정 등을 무효로 하여 그 효력을 없애는 것을 말한다.</li><li>**“타규정 연동개정”**이란 상위 법령이나 관련 규정 등의 개정·폐지에 따라 필요한 범위에서 해당 규정을 변경하는 것을 말한다.</li><li>**“일괄개정”**이란 두 개 이상의 규정 등을 동일한 목적이나 체계 정비 등을 위하여 하나의 개정안으로 동시에 개정하는 것을 말한다.</li><li>**“소관부서”**란 해당 규정 등에서 정한 업무를 실제로 집행·관리하는 부서를 말한다.</li><li>**“주관부서”**란 대표이사가 지정하여 규정관리 업무의 종합 조정 및 최종 해석을 담당하는 부서를 말한다. ② 이 규정에서 별도로 정하지 않는 용어는 관계 법령 및 재단 정관에서 사용하는 바에 따른다.</li></ol><h3 id="제3조-해석-1-규정-등의-해석에-관한-1차-책임은-해당-소관부서가-진다" tabindex="-1">제3조(해석) ① 규정 등의 해석에 관한 1차 책임은 해당 소관부서가 진다. <a class="header-anchor" href="#제3조-해석-1-규정-등의-해석에-관한-1차-책임은-해당-소관부서가-진다" aria-label="Permalink to &quot;제3조(해석) ① 규정 등의 해석에 관한 1차 책임은 해당 소관부서가 진다.&quot;">​</a></h3><p>② 부서 간 해석이 상충되는 경우 주관부서가 최종 해석한다. ③ 해석 결과는 전자결재시스템을 통해 공유하고 규정대장에도 반영한다.</p><h3 id="제4조-책무-및-책임-1-대표이사는-규정관리의-총괄-책임자로서-규정-등이-적시에-정확하게-이행되도록-관리·감독한다" tabindex="-1">제4조(책무 및 책임) ① 대표이사는 규정관리의 총괄 책임자로서 규정 등이 적시에, 정확하게 이행되도록 관리·감독한다. <a class="header-anchor" href="#제4조-책무-및-책임-1-대표이사는-규정관리의-총괄-책임자로서-규정-등이-적시에-정확하게-이행되도록-관리·감독한다" aria-label="Permalink to &quot;제4조(책무 및 책임) ① 대표이사는 규정관리의 총괄 책임자로서 규정 등이 적시에, 정확하게 이행되도록 관리·감독한다.&quot;">​</a></h3><p>② 소관부서 장은 소관 규정의 제정·개정·폐지 필요성을 주기적으로 검토하고, 필요한 경우 본 규정에 따른 절차를 이행하여야 한다. 단, 소관부서의 구체적 지정·변경 절차는 내규로 정한다. ③ 주관부서는 규정관리 업무의 전문부서로서 다음 각 호의 책무를 수행한다.</p><ol><li>규정 등 제·개정·폐지안의 사전심사 및 조정</li><li>규정관리 기준·서식의 운영 및 개선</li><li>규정관리 이력의 유지·보관 및 공개</li><li>필요시 규정집의 발간·추록 및 정비 ④ 내규에도 불구하고 지정되지 않은 업무에 대해서는 대표이사가 임시로 소관부서를 지정할 수 있다.</li></ol><h3 id="제5조-적용-범위-별도의-규정이-없는-한-재단의-모든-규정-등에-대하여-이-규정을-적용한다" tabindex="-1">제5조(적용 범위) 별도의 규정이 없는 한 재단의 모든 규정 등에 대하여 이 규정을 적용한다. <a class="header-anchor" href="#제5조-적용-범위-별도의-규정이-없는-한-재단의-모든-규정-등에-대하여-이-규정을-적용한다" aria-label="Permalink to &quot;제5조(적용 범위) 별도의 규정이 없는 한 재단의 모든 규정 등에 대하여 이 규정을 적용한다.&quot;">​</a></h3><h3 id="제6조-규정-및-내규-간의-효력-1-내규는-법령-또는-상위내규에-저촉되어서는-안되며-저촉되는-부분이-있는-경우에는-해당-부분의-효력이-상실된다" tabindex="-1">제6조(규정 및 내규 간의 효력) ① 내규는 법령 또는 상위내규에 저촉되어서는 안되며, 저촉되는 부분이 있는 경우에는 해당 부분의 효력이 상실된다. <a class="header-anchor" href="#제6조-규정-및-내규-간의-효력-1-내규는-법령-또는-상위내규에-저촉되어서는-안되며-저촉되는-부분이-있는-경우에는-해당-부분의-효력이-상실된다" aria-label="Permalink to &quot;제6조(규정 및 내규 간의 효력) ① 내규는 법령 또는 상위내규에 저촉되어서는 안되며, 저촉되는 부분이 있는 경우에는 해당 부분의 효력이 상실된다.&quot;">​</a></h3><p>② 정관, 규정, 내규 순으로 효력을 가진다. ③ 같은 순위의 규정 등 또는 같은 규정 등에서 조문 간 서로 저촉되는 부분이 있을 때에는 시간적으로 후에 시행된 것이 우선한다. 단, 이 경우에도 전 항의 사항을 따른다.</p><h3 id="제7조-규정의-분류-1-재단의-제규정은-그-성질과-내용에-따라-다음-각-호의-대분류로-구분한다" tabindex="-1">제7조(규정의 분류) ① 재단의 제규정은 그 성질과 내용에 따라 다음 각 호의 대분류로 구분한다. <a class="header-anchor" href="#제7조-규정의-분류-1-재단의-제규정은-그-성질과-내용에-따라-다음-각-호의-대분류로-구분한다" aria-label="Permalink to &quot;제7조(규정의 분류) ① 재단의 제규정은 그 성질과 내용에 따라 다음 각 호의 대분류로 구분한다.&quot;">​</a></h3><p>1. 조례·정관   2. 조직관리   3. 인사·복무   4. 보수   5. 재무·회계   6. 업무관리   7. 지원금·기부금관리   8. 공간운영·대관   9. 고객윤리 ② 중분류·소분류는 대분류별 기능·사항에 따라 필요 시 세분할 수 있다. ③ 이 조항에서 정하지 않은 세부 분류·번호 부여 기준은 내규로 정한다.</p><hr><h2 id="제2장-규정의-체계와-형식" tabindex="-1">제2장 규정의 체계와 형식 <a class="header-anchor" href="#제2장-규정의-체계와-형식" aria-label="Permalink to &quot;제2장 규정의 체계와 형식&quot;">​</a></h2><h3 id="제8조-체계-및-형식의-원칙-1-규정-등은-필요에-따라-장·절·조·항·호·목-순으로-편제한다-단-장·절·목은-두지-않을-수-있다" tabindex="-1">제8조(체계 및 형식의 원칙) ① 규정 등은 필요에 따라 장·절·조·항·호·목 순으로 편제한다. 단, 장·절·목은 두지 않을 수 있다. <a class="header-anchor" href="#제8조-체계-및-형식의-원칙-1-규정-등은-필요에-따라-장·절·조·항·호·목-순으로-편제한다-단-장·절·목은-두지-않을-수-있다" aria-label="Permalink to &quot;제8조(체계 및 형식의 원칙) ① 규정 등은 필요에 따라 장·절·조·항·호·목 순으로 편제한다. 단, 장·절·목은 두지 않을 수 있다.&quot;">​</a></h3><p>② 각 조문은 가급적 하나의 사항만을 규정한다. ③ 복문은 지양하여야 하며, 단문으로 분할하여 간결하게 표현함을 원칙으로 한다. ④ 조문의 주어는 명백히 표시하여야 하고, 조문의 술어는 규정하려는 의미에 따라 주어와 맞춰 작성하여야 한다. ⑤ 이외 조문구성의 작성방법과 형식은 내규로 정한다. 단, 내규 미제정 시에는 부칙을 따른다.</p><h3 id="제9조-체계편제-1-규정-등은-명칭-본칙과-부칙으로-구성한다" tabindex="-1">제9조(체계편제) ① 규정 등은 명칭, 본칙과 부칙으로 구성한다. <a class="header-anchor" href="#제9조-체계편제-1-규정-등은-명칭-본칙과-부칙으로-구성한다" aria-label="Permalink to &quot;제9조(체계편제) ① 규정 등은 명칭, 본칙과 부칙으로 구성한다.&quot;">​</a></h3><p>② 본칙은 다음 각 호를 필요에 따라 선택하여 구성한다.</p><ol><li>총칙 가. 목적 나. 정의 다. 적용범위 라. 다른 내규와의 관계</li><li>실체내용 가. 구체적인 사항의 구성 나. 사무의 흐름 순서로 구성 다. 중요도 및 적용빈도를 고려하여 구성</li><li>보칙 가. 총칙 및 실체조문에서 규정하기 적합하지 않은 사항의 구성 나. 절차적·기술적·보충적인 사항을 구성 ③ 부칙은 다음 각 호에 따라 구성한다. 단, 규정 제14조②항에 따라야 한다.</li><li>시행일에 관한 사항</li><li>기존 다른 내규의 존폐에 관한 사항</li><li>내규 시행에 따른 경과조치 또는 적용례에 관한 사항</li><li>그 밖에 부수적인 사항 ④ 이외 제규정의 구성과 작성방법은 내규로 정한다. 단, 내규 미제정 시에는 부칙 2조에 따른다.</li></ol><h3 id="제10조-용어-및-문장-1-용어는-법제처의-최신의-정비기준에-따른다" tabindex="-1">제10조(용어 및 문장) ① 용어는 법제처의 최신의 정비기준에 따른다. <a class="header-anchor" href="#제10조-용어-및-문장-1-용어는-법제처의-최신의-정비기준에-따른다" aria-label="Permalink to &quot;제10조(용어 및 문장) ① 용어는 법제처의 최신의 정비기준에 따른다.&quot;">​</a></h3><p>② 동일 개념에는 동일 용어를 사용하여야 한다. ③ 약어·외국어·전문용어 사용 시 그 뜻을 병기한다. 단, 병기는 첫 출연 시에만 작성하는 것으로 한정한다.</p><h3 id="제11조-별표·서식-등-1-내규의-내용에-대한-이해를-용이하게-하고자-하거나-계속적으로-사용하는-일정한-양식이-필요한-경우에는-부칙-다음에-별표-서식-등-이하-별표-등-이라-한다-을-사용할-수-있다" tabindex="-1">제11조(별표·서식 등) ① 내규의 내용에 대한 이해를 용이하게 하고자 하거나 계속적으로 사용하는 일정한 양식이 필요한 경우에는 부칙 다음에 별표, 서식 등(이하 “별표 등”이라 한다)을 사용할 수 있다. <a class="header-anchor" href="#제11조-별표·서식-등-1-내규의-내용에-대한-이해를-용이하게-하고자-하거나-계속적으로-사용하는-일정한-양식이-필요한-경우에는-부칙-다음에-별표-서식-등-이하-별표-등-이라-한다-을-사용할-수-있다" aria-label="Permalink to &quot;제11조(별표·서식 등) ① 내규의 내용에 대한 이해를 용이하게 하고자 하거나 계속적으로 사용하는 일정한 양식이 필요한 경우에는 부칙 다음에 별표, 서식 등(이하 “별표 등”이라 한다)을 사용할 수 있다.&quot;">​</a></h3><p>② 별표 등이 2개 이상인 경우에는 별표 등의 자구 다음에 일련번호를 붙여 [별표 ○] 또는 [별표 제○호서식]와 같이 “[]”를 붙여 표시한다. ③ 본칙 등에서 별표 등을 인용하는 경우에는 “[ ]”을 쓰지 않고 별표, 별지서식과 같이 인용한다.</p><hr><h2 id="제3장-규정의-제정·개정·폐지-절차" tabindex="-1">제3장 규정의 제정·개정·폐지 절차 <a class="header-anchor" href="#제3장-규정의-제정·개정·폐지-절차" aria-label="Permalink to &quot;제3장 규정의 제정·개정·폐지 절차&quot;">​</a></h2><h3 id="제12조-제안-1-규정-등의-제정·개정-또는-폐지-이하-제·개·폐-라-한다-는-다음-각-호의-자가-제안할-수-있다" tabindex="-1">제12조(제안) ① 규정 등의 제정·개정 또는 폐지(이하 “제·개·폐”라 한다)는 다음 각 호의 자가 제안할 수 있다. <a class="header-anchor" href="#제12조-제안-1-규정-등의-제정·개정-또는-폐지-이하-제·개·폐-라-한다-는-다음-각-호의-자가-제안할-수-있다" aria-label="Permalink to &quot;제12조(제안) ① 규정 등의 제정·개정 또는 폐지(이하 “제·개·폐”라 한다)는 다음 각 호의 자가 제안할 수 있다.&quot;">​</a></h3><ol><li>소관부서장</li><li>대표이사</li><li>윤리경영실장</li><li>그 밖에 대표이사가 필요하다고 인정하는 자 ② 제안자는 규정 등의 제·개·폐 사유서(별지 제1호 서식)에 제·개·폐 사유, 주요 내용, 예상 효과를 기재하여 주관부서에 제출하여야 한다. ③ 제안자는 조직·보수·인사 등 직원 권익에 중대한 영향을 미치는 규정은 주관부서 제출 전에 7일 이상 직원 의견수렴 절차를 거친다. 단, 내규에 따라 기간을 3일로 줄일 수 있다. ④ 주관부서는 필요에 따라 미제정 규정의 제정을 요구하거나 직접 제정할 수 있다.</li></ol><h3 id="제13조-사전검토-및-조정-1-주관부서는-제안받은-규정에-대하여-다음-각-호의-사항을-모두-검토한다" tabindex="-1">제13조(사전검토 및 조정) ① 주관부서는 제안받은 규정에 대하여 다음 각 호의 사항을 모두 검토한다. <a class="header-anchor" href="#제13조-사전검토-및-조정-1-주관부서는-제안받은-규정에-대하여-다음-각-호의-사항을-모두-검토한다" aria-label="Permalink to &quot;제13조(사전검토 및 조정) ① 주관부서는 제안받은 규정에 대하여 다음 각 호의 사항을 모두 검토한다.&quot;">​</a></h3><ol><li>상위 법령과의 정합성</li><li>규정 간 체계성</li><li>표현·용어의 적정성</li><li>행정절차의 명확성</li><li>필요한 경우 내부 의견수렴 결과 ② 검토 과정에서 소관부서 및 관계부서와 협의가 필요한 경우 주관부서는 7일 이내의 기한을 정하여 의견 회신을 요청할 수 있다. ③ 주관부서는 검토 결과를 검토의견서로 작성하여 소관부서에 통보하여야 하며, 소관부서는 해당 의견을 반영하여 규정등의 제·개정·폐지 절차를 진행하여야 한다.</li></ol><h3 id="제14조-의결-및-승인-1-규정-제·개·폐-안은-이사회의-의결을-거친다" tabindex="-1">제14조(의결 및 승인) ① 규정 제·개·폐 안은 이사회의 의결을 거친다. <a class="header-anchor" href="#제14조-의결-및-승인-1-규정-제·개·폐-안은-이사회의-의결을-거친다" aria-label="Permalink to &quot;제14조(의결 및 승인) ① 규정 제·개·폐 안은 이사회의 의결을 거친다.&quot;">​</a></h3><p>② 내규는 대표이사의 승인을 얻어 제·개·폐 안을 시행한다. 다만, 소관부서장은 차기이사회에 내규에 관한 사항을 보고하여야 한다. ③ 이사회 의결 또는 대표이사 승인 후 주관부서장은 전자결재시스템과 재단 누리집에 규정집을 게시하여야 한다.</p><h3 id="제15조-공포-및-시행-1-규정은-이사회-의결-내규는-대표이사-결재를-받은-날을-공포일로-한다-단-공포된-날부터-일정-기간이-경과한-후에-시행되는-경우-그-공포일을-기간-계산에-포함하지-않는다" tabindex="-1">제15조(공포 및 시행) ① 규정은 이사회 의결, 내규는 대표이사 결재를 받은 날을 공포일로 한다. 단, 공포된 날부터 일정 기간이 경과한 후에 시행되는 경우, 그 공포일을 기간 계산에 포함하지 않는다. <a class="header-anchor" href="#제15조-공포-및-시행-1-규정은-이사회-의결-내규는-대표이사-결재를-받은-날을-공포일로-한다-단-공포된-날부터-일정-기간이-경과한-후에-시행되는-경우-그-공포일을-기간-계산에-포함하지-않는다" aria-label="Permalink to &quot;제15조(공포 및 시행) ① 규정은 이사회 의결, 내규는 대표이사 결재를 받은 날을 공포일로 한다. 단, 공포된 날부터 일정 기간이 경과한 후에 시행되는 경우, 그 공포일을 기간 계산에 포함하지 않는다.&quot;">​</a></h3><p>② 규정의 시행일은 공포한 날부터로 한다. 다만, 다음 각 호의 경우에는 부칙에 따로 시행일을 정할 수 있다.   1. 적용례: 새로 제정하거나 개정한 규정의 적용 대상·단계를 명시하는 경우   2. 경과조치: 기득권 보호 등을 위하여 특정 대상에 이전 규정을 계속 적용하는 경우   3. 시행일 지정: 공포한 날이 아닌 다른 날을 시행일로 지정하는 경우 4. 유효기간: 규정 또는 내규의 존속기한을 정하여, 유효기간이 지나면 해당 내용을 실효되어 폐지된 것으로 간주하는 경우 ③ 상위 법령이 개정되어 규정을 개정할 때에도 소급적용은 할 수 없다. 다만, 다음 호에 해당될 경우 예외적으로 적용할 수 있다.   1. 임직원에게 유리한 적용에 해당하는 사항의 경우</p><h3 id="제16조-규정대장-관리-1-주관부서는-규정대장을-비치·관리하여야-하며-규정대장에는-다음-각-호의-사항을-기록한다" tabindex="-1">제16조(규정대장 관리) ① 주관부서는 규정대장을 비치·관리하여야 하며, 규정대장에는 다음 각 호의 사항을 기록한다. <a class="header-anchor" href="#제16조-규정대장-관리-1-주관부서는-규정대장을-비치·관리하여야-하며-규정대장에는-다음-각-호의-사항을-기록한다" aria-label="Permalink to &quot;제16조(규정대장 관리) ① 주관부서는 규정대장을 비치·관리하여야 하며, 규정대장에는 다음 각 호의 사항을 기록한다.&quot;">​</a></h3><ol><li>규정명 및 번호</li><li>소관부서</li><li>제·개·폐 연혁</li><li>관련 상위법령 및 관련 규정</li><li>시행일 및 공포번호</li><li>해석에 관한 사항 ② 규정대장은 규정집과 함께 관리하여야 하며, 모든 임직원은 이를 열람할 수 있다. ③ 규정번호는 주관부서장이 일련번호와 연도를 조합하여 부여한다. ④ 규정 및 내규(폐지·개정 규정 포함)의 전자 원본을 관리하여야 한다.</li></ol><hr><h2 id="제4장-운영-및-정비" tabindex="-1">제4장 운영 및 정비 <a class="header-anchor" href="#제4장-운영-및-정비" aria-label="Permalink to &quot;제4장 운영 및 정비&quot;">​</a></h2><h3 id="제17조-정기점검-및-일몰검토-1-주관부서는-규정-등에-대한-정기점검을-실시할-수-있다" tabindex="-1">제17조(정기점검 및 일몰검토) ① 주관부서는 규정 등에 대한 정기점검을 실시할 수 있다. <a class="header-anchor" href="#제17조-정기점검-및-일몰검토-1-주관부서는-규정-등에-대한-정기점검을-실시할-수-있다" aria-label="Permalink to &quot;제17조(정기점검 및 일몰검토) ① 주관부서는 규정 등에 대한 정기점검을 실시할 수 있다.&quot;">​</a></h3><p>② 주관부서는 다음 각 호에 해당될 경우 폐지·통합을 포함한 일몰검토를 실시 할 수 있다.</p><ol><li>최근 2년간 적용 사례가 없는 경우</li><li>상위 법령이나 정관이 폐지·개정되어 근거가 소멸된 경우</li><li>동일·유사한 내용의 규정 등이 중복되어 있는 경우</li></ol><h3 id="제18조-타규정-연동개정-운영-1-상위-법령이나-관련-규정이-제·개·폐된-경우-소관부서장은-해당-법령·규정의-공포일부터-30일-이내에-해당-규정의-제·개·폐-필요성을-검토하여-주관부서에-통보한다" tabindex="-1">제18조(타규정 연동개정 운영) ① 상위 법령이나 관련 규정이 제·개·폐된 경우 소관부서장은 해당 법령·규정의 공포일부터 30일 이내에 해당 규정의 제·개·폐 필요성을 검토하여 주관부서에 통보한다. <a class="header-anchor" href="#제18조-타규정-연동개정-운영-1-상위-법령이나-관련-규정이-제·개·폐된-경우-소관부서장은-해당-법령·규정의-공포일부터-30일-이내에-해당-규정의-제·개·폐-필요성을-검토하여-주관부서에-통보한다" aria-label="Permalink to &quot;제18조(타규정 연동개정 운영) ① 상위 법령이나 관련 규정이 제·개·폐된 경우 소관부서장은 해당 법령·규정의 공포일부터 30일 이내에 해당 규정의 제·개·폐 필요성을 검토하여 주관부서에 통보한다.&quot;">​</a></h3><p>② 주관부서는 관계 규정을 연동하여 연동개정 할 수 있다. 이 경우 부칙으로 개정함을 원칙으로 하며, 단순 자구수정 해당하는 경우에는 대표이사 전결로 갈음하고, 그 결과를 차기 이사회에 보고한다.<br> ③ 처리 절차·방법 및 자구수정의 범위 포함 작성 기준은 내규를 따른다.</p><h3 id="제19조-일괄개정-운영-1-다음-각-호-모두에-해당하는-경우-주관부서는-○○규정-등-일괄개정규정-별도-규정-을-제정하여-일괄개정을-시행할-수-있다" tabindex="-1">제19조(일괄개정 운영) ① 다음 각 호 모두에 해당하는 경우 주관부서는 ‘○○규정 등 일괄개정규정’(별도 규정)을 제정하여 일괄개정을 시행할 수 있다. <a class="header-anchor" href="#제19조-일괄개정-운영-1-다음-각-호-모두에-해당하는-경우-주관부서는-○○규정-등-일괄개정규정-별도-규정-을-제정하여-일괄개정을-시행할-수-있다" aria-label="Permalink to &quot;제19조(일괄개정 운영) ① 다음 각 호 모두에 해당하는 경우 주관부서는 ‘○○규정 등 일괄개정규정’(별도 규정)을 제정하여 일괄개정을 시행할 수 있다.&quot;">​</a></h3><ol><li>규정 간 정책목적이나 서식·용어·번호 체계 통일이 필요할 것</li><li>같은 공포일과 시행일로 처리할 것</li><li>개정 권한이 같은 단위(이사회·대표이사)일 것 ② 일괄개정규정의 부칙으로 유효기간을 명시하여 경과 후 해당 규정은 자동 폐지함을 원칙으로 한다.<br> ③ 처리절차·방법 및 내용은 내규를 따른다.</li></ol><h3 id="제20조-정비에-관한-사항-규정의-정기점검·일몰검토-규정대장-관리-서식·매뉴얼의-작성·개정-그-밖에-규정의-관리-원칙-및-방법에-관한-세부-사항은-별도-내규로-정한다" tabindex="-1">제20조(정비에 관한 사항) 규정의 정기점검·일몰검토, 규정대장 관리, 서식·매뉴얼의 작성·개정, 그 밖에 규정의 관리 원칙 및 방법에 관한 세부 사항은 별도 내규로 정한다. <a class="header-anchor" href="#제20조-정비에-관한-사항-규정의-정기점검·일몰검토-규정대장-관리-서식·매뉴얼의-작성·개정-그-밖에-규정의-관리-원칙-및-방법에-관한-세부-사항은-별도-내규로-정한다" aria-label="Permalink to &quot;제20조(정비에 관한 사항) 규정의 정기점검·일몰검토, 규정대장 관리, 서식·매뉴얼의 작성·개정, 그 밖에 규정의 관리 원칙 및 방법에 관한 세부 사항은 별도 내규로 정한다.&quot;">​</a></h3><hr><h2 id="제5장-보칙" tabindex="-1">제5장 보칙 <a class="header-anchor" href="#제5장-보칙" aria-label="Permalink to &quot;제5장 보칙&quot;">​</a></h2><h3 id="제21조-규정관리의-원칙-1-규정-등은-재단의-설립목적과-경영목표가-합리적이고-효율적으로-구현될-수-있도록-제정되어야-한다" tabindex="-1">제21조(규정관리의 원칙) ① 규정 등은 재단의 설립목적과 경영목표가 합리적이고 효율적으로 구현될 수 있도록 제정되어야 한다. <a class="header-anchor" href="#제21조-규정관리의-원칙-1-규정-등은-재단의-설립목적과-경영목표가-합리적이고-효율적으로-구현될-수-있도록-제정되어야-한다" aria-label="Permalink to &quot;제21조(규정관리의 원칙) ① 규정 등은 재단의 설립목적과 경영목표가 합리적이고 효율적으로 구현될 수 있도록 제정되어야 한다.&quot;">​</a></h3><p>② 재단의 업무 수행에 근거할 규범과 기준은 이 규정이 정하는 바에 따라 가능한 규정과 내규로 정하여야 한다.</p><h3 id="제22조-대표이사-방침서의-관리-1-방침서는-대표이사가-결재한-문서로-지침-매뉴얼-등의-명칭으로-내규적-특성을-띤-문서를-말한다-단-사업운영을-위한-보고-또는-계획의-방침서는-제외한다" tabindex="-1">제22조(대표이사 방침서의 관리) ① 방침서는 대표이사가 결재한 문서로 지침, 매뉴얼 등의 명칭으로 내규적 특성을 띤 문서를 말한다. 단, 사업운영을 위한 보고 또는 계획의 방침서는 제외한다. <a class="header-anchor" href="#제22조-대표이사-방침서의-관리-1-방침서는-대표이사가-결재한-문서로-지침-매뉴얼-등의-명칭으로-내규적-특성을-띤-문서를-말한다-단-사업운영을-위한-보고-또는-계획의-방침서는-제외한다" aria-label="Permalink to &quot;제22조(대표이사 방침서의 관리) ① 방침서는 대표이사가 결재한 문서로 지침, 매뉴얼 등의 명칭으로 내규적 특성을 띤 문서를 말한다. 단, 사업운영을 위한 보고 또는 계획의 방침서는 제외한다.&quot;">​</a></h3><p>② 방침서는 비내규성의 문서로 관리하며, 규정의 편성 원칙에 구애됨이 없이 일반문서 형식으로 작성한다. ③ 방침서를 작성 및 배포하는 부서에서는 대표이사 결재를 승인받은 후 30일 이내로 주관부서에 통보하여야 한다.</p><hr><h2 id="부칙" tabindex="-1">부칙 <a class="header-anchor" href="#부칙" aria-label="Permalink to &quot;부칙&quot;">​</a></h2><h3 id="제1조-시행일" tabindex="-1">제1조(시행일) <a class="header-anchor" href="#제1조-시행일" aria-label="Permalink to &quot;제1조(시행일)&quot;">​</a></h3><p>이 규정은 2025년 ○월 ○일부터 시행한다.</p><h3 id="제2조-적용례" tabindex="-1">제2조(적용례) <a class="header-anchor" href="#제2조-적용례" aria-label="Permalink to &quot;제2조(적용례)&quot;">​</a></h3><p>이 규정의 전면개정에 따라, 내규가 제정될 때 까지의 제·개정절차는 이전의 규정에 정한 바에 따른다.</p><h3 id="제3조-경과조치" tabindex="-1">제3조(경과조치) <a class="header-anchor" href="#제3조-경과조치" aria-label="Permalink to &quot;제3조(경과조치)&quot;">​</a></h3><p>이 규정의 시행 전에 진행 중인 규정 제·개·폐 절차는 이 규정에 따라 진행된 것으로 본다. 다만, 필요한 경우 주관부서의 검토를 거쳐 보완할 수 있다.</p><hr><h3 id="부속-서식-목록" tabindex="-1">부속 서식 목록 <a class="header-anchor" href="#부속-서식-목록" aria-label="Permalink to &quot;부속 서식 목록&quot;">​</a></h3><ul><li>(별지 제1호) 규정 제·개·폐 사유서</li><li>(별지 제2호) 규정 검토의견서</li><li>(별지 제3호) 규정대장</li></ul>',65)]))}const q=l(o,[["render",h]]);export{b as __pageData,q as default};
